    ],
    "authors": [
        {
            "name": "Théo FIDRY",
            "email": "theo.fidry@gmail.com"
        }
    ],
    "require": {
        "php": "^7.2 || ^8.0"
    },
    "require-dev": {
        "fidry/makefile": "^0.2.0",
        "fidry/php-cs-fixer-config": "^1.1.2",
        "phpstan/extension-installer": "^1.2.0",
        "phpstan/phpstan": "^2.0",
        "phpstan/phpstan-deprecation-rules": "^2.0.0",
        "phpstan/phpstan-phpunit": "^2.0",
